param([string]$GameRoot='F:/SteamLibrary/steamapps/common/RimWorld')
# Read-only extraction of selected gameplay data and derived-source pointers.
$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$out=Join-Path $root 'docs/research/rimworld/evidence'
function Source([string]$file,[int]$start=1,[int]$end=0){
 $p=Join-Path $root $file;$lines=Get-Content -LiteralPath $p
 if(!$end){$end=$lines.Count};if($start -lt 1 -or $end -gt $lines.Count -or $end -lt $start){throw "Invalid range $file"}
 [ordered]@{file=$file;sha256=(Get-FileHash -LiteralPath $p).Hash.ToLowerInvariant();lines=@($start,$end)}
}
$s='.local-research/social-interaction';$x='.local-research/social-interaction-extra';$m='.local-research/mood-recreation'
$claims=@(
 [ordered]@{id='SC01';finding='Random social events are not conversation jobs. TryInteractWith validates, adds memories and XP, considers social fighting, invokes worker, creates interaction bubble and PlayLogEntry, and updates both last-interaction trackers. The selected three workers override selection weight only; base Interacted only initializes output fields.';sources=@((Source "$s/RimWorld.Pawn_InteractionsTracker.cs" 176 269),(Source "$x/RimWorld.InteractionWorker.cs"),(Source "$s/RimWorld.InteractionWorker_Chitchat.cs"),(Source "$s/RimWorld.InteractionWorker_DeepTalk.cs"),(Source "$s/RimWorld.InteractionWorker_Insult.cs"));xml=@('SX01')},
 [ordered]@{id='SC02';finding='Random eligibility is asymmetric: initiator requires interaction tracker, Talking, awake, no fire/block, humanlike, not downed/aggressive, faction and life-stage permission; receiver does not repeat Talking/Hearing requirements. Position requires horizontal range6 and line of sight. Mental-state blocks, blocking hediffs and lord restrictions are checked through PawnUtility.';sources=@((Source "$s/RimWorld.SocialInteractionUtility.cs" 10 155),(Source '.local-research/housing/RimWorld.PawnUtility.cs' 43 82));xml=@()},
 [ordered]@{id='SC03';finding='Current social mode derives from job/duty/draft/mental state; Off clears intent, Quiet clears it each interval. After >320ticks, hash60 tests MTB22000/6600/550 for Quiet/Normal/SuperActive. Failed intent retries on hash91. Generic initiator cooldown120, no symmetric receiver cooldown here. Candidates are spawned same-faction pawns, shuffled, with weighted InteractionDefs and global Rand.';sources=@((Source "$s/RimWorld.Pawn_InteractionsTracker.cs" 10 174),(Source "$s/RimWorld.Pawn_InteractionsTracker.cs" 300 353));xml=@()},
 [ordered]@{id='SC04';finding='Chitchat weight1, DeepTalk .075 times compatibility curve, Insult .007 times negative factor. Kind initiator nullifies negative interactions; Abrasive multiplies2.3. Negative factor uses directional opinion and fixed-pair compatibility, not mood. Slave-to-nonslave insults are suppressed. Weights compete with all other applicable InteractionDefs, so are not unconditional probabilities.';sources=@((Source "$s/RimWorld.InteractionWorker_Chitchat.cs"),(Source "$s/RimWorld.InteractionWorker_DeepTalk.cs"),(Source "$s/RimWorld.InteractionWorker_Insult.cs"),(Source "$x/RimWorld.NegativeInteractionUtility.cs"));xml=@('SX01')},
 [ordered]@{id='SC05';finding='Interaction thoughts use the OTHER pawn SocialImpact at creation: moodPowerFactor and social opinionOffset are scaled before TryGainMemory. Chitchat/DeepTalk affect both participants; Insulted affects recipient. Social XP4/10 belongs to initiator. Actual directional amounts may differ.';sources=@((Source "$s/RimWorld.Pawn_InteractionsTracker.cs" 176 220),(Source "$s/RimWorld.Pawn_InteractionsTracker.cs" 285 298));xml=@('SX01','SX02','SX03')},
 [ordered]@{id='SC06';finding='SocialImpact: base1,min.2, Social skill factor .82+.0275*L; capacity factors Talking weight.9 and Hearing.3 each allowedDefect.05,max1. Capacity c<1 becomes clamp01(c/.95); each contributes1-weight+weight*q. Other stat offsets/factors remain possible.';sources=@((Source '.local-research/skills/RimWorld.SkillNeed_BaseBonus.cs' 6 27),(Source '.local-research/skills/RimWorld.PawnCapacityFactor.cs'),(Source '.local-research/housing/RimWorld.StatWorker.cs' 366 397));xml=@('SX03')},
 [ordered]@{id='SC07';finding='Chitchat is cumulative: new .66*otherImpact merges into same-def same-other offset without resetting age. Internal amount can exceed10; only opinion contribution is capped10. Every accumulated60000ticks it moves1 toward zero and resets age; offset==0 discards. It overrides ordinary duration and age fading.';sources=@((Source "$x/RimWorld.Thought_MemorySocialCumulative.cs"));xml=@('SX02')},
 [ordered]@{id='SC08';finding='DeepTalk+15 and Insulted-15 have20day duration,300 total and10 per other, stacking.9. Ordinary social memories never merge, fade only after default70% duration, and discard after age>duration (or missing other/zero offset). Memory interval adds150ticks; stored offsets and age are persisted.';sources=@((Source "$s/RimWorld.Thought_MemorySocial.cs"),(Source "$x/RimWorld.ThoughtDef.cs"),(Source "$m/RimWorld.Thought_Memory.cs" 44 67),(Source "$m/RimWorld.Thought_Memory.cs" 118 139));xml=@('SX02')},
 [ordered]@{id='SC09';finding='Opinion groups exclude zero contributors, sort memory age ascending (newest first), sum faded offsets times stacking powers, round each group with nonzero minimum +/-1, then sum groups. Overflow removes oldest per-other then oldest same-def. OpinionOf adds relation and situation offsets, hediff factor, hostile positive clamp and final[-100,100].';sources=@((Source "$m/RimWorld.ThoughtHandler.cs" 132 224),(Source "$m/RimWorld.MemoryThoughtHandler.cs" 142 249),(Source "$s/RimWorld.Pawn_RelationsTracker.cs" 592 629));xml=@('SX02')},
 [ordered]@{id='SC10';finding='Insulted creates a separate InsultedMood via fresh TryGainMemory(def,other); it does not inherit SocialImpact moodPowerFactor. Mood-5 lasts2days,stack10,.9. Ordinary memory groups with different otherPawn when formatted labels match, as fixed insulted label does; full-group merge renews oldest age rather than creating an11th.';sources=@((Source "$m/RimWorld.MemoryThoughtHandler.cs" 142 212),(Source "$m/RimWorld.Thought_Memory.cs" 140 186));xml=@('SX02')},
 [ordered]@{id='SC11';finding='Compatibility is not opinion: age difference0..20 maps .45..-.45 plus stable pair-seeded asymmetric Gaussian(.3,1,1.4); seed=(idA XOR idB)*37. PushState/PopState preserves outer RNG. Directional opinion remains independently computed.';sources=@((Source "$s/RimWorld.Pawn_RelationsTracker.cs" 815 834));xml=@()},
 [ordered]@{id='SC12';finding='GatherSpot newly constructed active=true; save active default=false; nonplayer fresh spawns deactivate. Changes register/unregister in activeSpots; toggle is ordinary UI and despawn unregisters. TableGatherSpotBase adds CompGatherSpot to dining tables.';sources=@((Source "$x/RimWorld.CompGatherSpot.cs"),(Source "$x/RimWorld.GatherSpotLister.cs"));xml=@('SX06')},
 [ordered]@{id='SC13';finding='SocialRelax selects active gathering spots with reachability/safety/propriety checks. Eat-surface tables require an adjacent free sittable (30 random cardinal-cell attempts), without ground fallback. Non-Eat spots search chairs within3.9 then valid ground. No companion requirement exists in this giver. Optional nurseable recreational drink is not required.';sources=@((Source "$x/RimWorld.JoyGiver_SocialRelax.cs"));xml=@('SX04','SX06')},
 [ordered]@{id='SC14';finding='SocialRelax reserves actual seat/spot, walks there, faces gather spot, gains comfort and Social joy, with SuperActive mode during the delayed toil. Duration4000,JoyGiver relative baseChance4. Full joy can end early; room thought occurs on finish. No dialogue event must happen to gain recreation.';sources=@((Source '.local-research/environment-storage/RimWorld.JobDriver_SocialRelax.cs'));xml=@('SX04','SX05')},
 [ordered]@{id='SC15';finding='Interaction log persists intDef,initiator,recipient,extra rules and faction/ideology; tracker persists wantsRandomInteract,lastInteractionTime,lastInteraction,lastInteractionDef. Visible bubbles are transient presentation; durable log and memories establish participants/effect.';sources=@((Source "$s/Verse.PlayLogEntry_Interaction.cs" 193 202),(Source "$s/RimWorld.Pawn_InteractionsTracker.cs" 96 104),(Source "$s/RimWorld.Pawn_InteractionsTracker.cs" 223 269));xml=@('SX01')},
 [ordered]@{id='SC16';finding='Insult socialFightBaseChance.04 is only a base. SocialFightPossible checks awake/downed/mental/faction/violence and more, while SocialFightChance uses opinion, traits, capacities, curves and other factors. A fixed4% unconditional fight probability is unsupported.';sources=@((Source "$s/RimWorld.Pawn_InteractionsTracker.cs" 355 487));xml=@('SX01')}
)
$specs=@(
 @('SX01','Data/Core/Defs/InteractionDefs/Interactions_Social.xml','/Defs/InteractionDef[defName="Chitchat" or defName="DeepTalk" or defName="Insult"]'),
 @('SX02','Data/Core/Defs/ThoughtDefs/Thoughts_Memory_Social.xml','/Defs/ThoughtDef[defName="Chitchat" or defName="DeepTalk" or defName="Insulted" or defName="InsultedMood"]'),
 @('SX03','Data/Core/Defs/Stats/Stats_Pawns_Social.xml','/Defs/StatDef[defName="SocialImpact"]'),
 @('SX04','Data/Core/Defs/Joy/JoyGivers.xml','/Defs/JoyGiverDef[defName="SocialRelax"]'),
 @('SX05','Data/Core/Defs/JobDefs/Jobs_Joy.xml','/Defs/JobDef[defName="SocialRelax"]'),
 @('SX06','Data/Core/Defs/ThingDefs_Buildings/Buildings_Furniture.xml','/Defs/ThingDef[@Name="TableBase" or @Name="TableGatherSpotBase" or defName="Table1x2c"]')
)
$keep=@('defName','workerClass','thoughtClass','initiatorThought','recipientThought','socialFightBaseChance','initiatorXpGainAmount','initiatorXpGainSkill','thoughtToMake','durationDays','stackLimit','stackLimitForSameOtherPawn','stackedEffectMultiplier','maxCumulatedOpinionOffset','nullifyingTraits','nullifyingHediffs','developmentalStageFilter','defaultBaseValue','minValue','skillNeedFactors','capacityFactors','neverDisabled','giverClass','baseChance','jobDef','joyKind','driverClass','joyDuration','surfaceType','size','costStuffCount')
$xml=@(foreach($spec in $specs){
 $path=Join-Path $GameRoot $spec[1];$doc=[xml](Get-Content -LiteralPath $path -Raw);$nodes=$doc.SelectNodes($spec[2]);if(!$nodes.Count){throw "Empty XPath $($spec[0])"}
 $selected=@(foreach($node in $nodes){
  $copy=$node.CloneNode($false)
  foreach($child in $node.ChildNodes){
   if($child.LocalName -in $keep){[void]$copy.AppendChild($child.CloneNode($true))}
   elseif($child.LocalName -eq 'stages'){$sc=$child.CloneNode($false);foreach($li in $child.SelectNodes('li')){$lc=$li.CloneNode($false);foreach($v in $li.ChildNodes){if($v.LocalName -in @('baseMoodEffect','baseOpinionOffset')){[void]$lc.AppendChild($v.CloneNode($true))}};[void]$sc.AppendChild($lc)};[void]$copy.AppendChild($sc)}
   elseif($child.LocalName -eq 'comps'){$cc=$child.CloneNode($false);foreach($li in $child.SelectNodes('li[compClass="CompGatherSpot"]')){[void]$cc.AppendChild($li.CloneNode($true))};[void]$copy.AppendChild($cc)}
  };$copy.OuterXml
 })
 [ordered]@{id=$spec[0];file=$spec[1];source_sha256=(Get-FileHash -LiteralPath $path).Hash.ToLowerInvariant();xpath=$spec[2];projection='Original attributes and selected gameplay children only; stages retain numeric offsets, not descriptions';nodes=$selected}
})
$manifest=Get-Content (Join-Path $out 'social-interaction-manifest.json') -Raw|ConvertFrom-Json
$prior=Get-Content (Join-Path $out 'dining-comfort-evidence.json') -Raw|ConvertFrom-Json
$e=[ordered]@{evidence_id='RW17-SOCIAL-INTERACTION-MECHANISMS';date_local='2026-11-04';version_text=$manifest.version_text;source_sha256=$manifest.source_sha256;kind='Static ILSpy-derived C# and selected shipped Core XML';manifests=@('social-interaction-manifest.json','social-interaction-extra-manifest.json');claims=$claims;xml=$xml;rea_members=$prior.rea_members;native_runtime_report='../98-native-social-runtime.md';limitations=@('Derived C# is not original source. Existing matching derivations reused; full C# remains local.','REA67108864byte member-budget failure is retained and was not repeatedly requested.','Selected Core XML is not the fully patched active Def database.','No probability calibration or proof that every dependency branch was executed; native observations separate.')}
[IO.File]::WriteAllText((Join-Path $out 'social-interaction-evidence.json'),($e|ConvertTo-Json -Depth 18).Replace("`r`n","`n")+"`n",[Text.UTF8Encoding]::new($false))
"$($claims.Count) claims; $($xml.Count) XML selections."
